def bnd(out):
    d = out if isinstance(out, dict) else {}
    wb = d.get('world_bounds_m', {})
    def r3(v):
        return [round(x, 3) for x in v] if v else None
    return {'ev': d.get('evidence_id'), 'c': r3(wb.get('center')), 'mn': r3(wb.get('min')), 'mx': r3(wb.get('max')), 'med': r3(d.get('world_median_m')), 'px': d.get('pixel_count')}

rc = primitives.call(name='observe_maniskill_control_state')
print('CTRL', rc.ok)
print('keys', list(rc.output.keys()) if isinstance(rc.output, dict) else type(rc.output))
print(str(rc.output)[:900])

for sid in [18, 19]:
    ri = primitives.call(name='inspect_maniskill_instance', camera_uid='base_camera', segmentation_id=sid)
    print('BASE', sid, ri.ok, bnd(ri.output))

for sid in [18, 19]:
    ri = primitives.call(name='inspect_maniskill_instance', camera_uid='hand_camera', segmentation_id=sid)
    print('HAND', sid, ri.ok, bnd(ri.output))
